def countLimitedCombos(coins, counts, amount):
    MOD = 1000000007
    ways = [0] * (amount + 1)
    ways[0] = 1
    for c, k in zip(coins, counts):
        new = [0] * (amount + 1)
        for s in range(amount + 1):
            v = ways[s]
            if s >= c:
                v += new[s - c]
            if s - (k + 1) * c >= 0:
                v -= ways[s - (k + 1) * c]
            new[s] = v % MOD
        ways = new
    return ways[amount]
